import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';
import { LogoutButton } from './logout-button';

interface Organization { id:string; name:string; slug:string; tier:{name:string;maxActiveEvents:number;maxParticipantsPerEvent:number}; memberships:Array<{role:string}> }
async function api<T>(path:string,token:string):Promise<T>{const response=await fetch(`${process.env.API_INTERNAL_URL}/api/${path}`,{headers:{authorization:`Bearer ${token}`},cache:'no-store'});if(response.status===401)redirect('/login');if(!response.ok)throw new Error('API isteği başarısız.');return response.json() as Promise<T>}
export default async function Dashboard(){const token=(await cookies()).get('eventise_session')?.value;if(!token)redirect('/login');const organizations=await api<Organization[]>('organizations',token);if(!organizations.length)redirect('/onboarding');const organization=organizations[0],limits=await api<Record<string,string|number|boolean>>(`organizations/${organization.id}/tier/limits`,token);return <main className="app-shell"><aside className="app-nav"><div className="logo"><b>e</b>eventise</div><div className="org-chip"><span>{organization.name.slice(0,2).toUpperCase()}</span><div><b>{organization.name}</b><small>{organization.memberships[0]?.role.replaceAll('_',' ')}</small></div></div><nav><a className="active">⌂ Genel bakış</a><a>◇ Etkinlikler</a><a>♧ Katılımcılar</a><a>✉ İletişim</a><a>▤ Formlar</a><a>▣ Etkinlik günü</a></nav><LogoutButton/></aside><section className="dashboard"><header><div><p className="eyebrow">KURUM PANELİ</p><h1>{organization.name}</h1><p>Gerçek API ve PostgreSQL verileriyle çalışan Aşama 1 yönetim alanı.</p></div><span className="tier-badge">{organization.tier.name}</span></header><div className="metric-grid"><article><span>Aktif etkinlik limiti</span><b>{String(limits.maxActiveEvents)}</b><small>Veritabanından çözülür</small></article><article><span>Etkinlik katılımcı limiti</span><b>{String(limits.maxParticipantsPerEvent)}</b><small>Kurum istisnaları uygulanır</small></article><article><span>Fotoğraf depolama</span><b>{Math.round(Number(limits.photoStorageLimitBytes)/1024/1024/1024)} GB</b><small>S3 uyumlu depolama</small></article><article><span>E-posta çarpanı</span><b>× {String(limits.emailMultiplier)}</b><small>Aylık dinamik kota</small></article></div><section className="phase-card"><div><span className="status-dot"></span><p className="eyebrow">AŞAMA 1 · ALTYAPI</p><h2>Çalışma alanınız hazır</h2><p>Kimlik doğrulama, kurum kapsamı, rol politikaları, tier/kota, audit, kuyruk ve sağlayıcı adaptörleri etkin.</p></div><ul><li>PostgreSQL tenant izolasyonu</li><li>HttpOnly oturum</li><li>Swagger belgeli REST API</li><li>API + worker süreçleri</li></ul></section></section></main>}
